import re
from collections import Counter

def top_5xx_ips(log_lines: list[str]) -> list[tuple[str, int]]:
    pattern = r'^(\S+) .*? "\w+ .*?" (5\d{2}) '
    ip_counts = Counter()
    for line in log_lines:
        match = re.search(pattern, line)
        if match:
            ip, status = match.groups()
            ip_counts[ip] += 1
    return ip_counts.most_common(5)

