import time
import urllib.request

def check_service_health(url: str, max_retries: int = 4) -> dict:
    delay = 1.0
    for attempt in range(1, max_retries + 1):
        start = time.time()
        try:
            req = urllib.request.Request(url, headers={'User-Agent': 'HealthCheck/1.0'})
            with urllib.request.urlopen(req, timeout=5) as res:
                if res.status == 200:
                    return {'status': 'healthy', 'latency_ms': round((time.time() - start) * 1000), 'attempts': attempt}
        except Exception:
            if attempt == max_retries:
                return {'status': 'down', 'latency_ms': None, 'attempts': attempt}
            time.sleep(delay)
            delay *= 2
    return {'status': 'unknown'}

