import re

def scan_for_secrets(file_content: str) -> list[dict]:
    findings = []
    aws_pattern = re.compile(r'(AKIA[0-9A-Z]{16})')
    jwt_pattern = re.compile(r'eyJ[a-zA-Z0-9_-]{10,}\.eyJ[a-zA-Z0-9_-]{10,}\.[a-zA-Z0-9_-]{10,}')
    for line_num, line in enumerate(file_content.splitlines(), start=1):
        for match in aws_pattern.finditer(line):
            findings.append({'line': line_num, 'type': 'AWS Key', 'token': match.group()[:6] + '...REDACTED'})
        for match in jwt_pattern.finditer(line):
            findings.append({'line': line_num, 'type': 'JWT', 'token': match.group()[:10] + '...REDACTED'})
    return findings

