import hmac
import hashlib

def verify_webhook(payload: bytes, secret: str, received_sig: str) -> bool:
    expected_sig = hmac.new(
        secret.encode('utf-8'),
        payload,
        hashlib.sha256
    ).hexdigest()
    # Use hmac.compare_digest for constant-time comparison
    return hmac.compare_digest(expected_sig, received_sig)
